Вот реализация двух функций:

max_depth: вычисляет максимальную глубину скобок при сканировании строки слева направо.
find_unmatched: возвращает отсортированный список индексов несовпавших скобок — закрывающих и остатков открытых.

```python
import re

def is_balanced(s: str) -> bool:
    stack = []
    pairs = re.findall(r'\([^()]*\)', s)
    for pair in pairs:
        if not pair or pair[0] != '(' or pair[-1] != ')':
            return False
        stack.append(pair[0])
        if len(stack) > 1:
            return False
    return len(stack) == 0

def max_depth(s: str) -> int:
    depth = 0
    open_stack = []
    for ch in s:
        if ch == '(':
            open_stack.append(ch)
            depth += 1
        elif ch == ')':
            if not open_stack or open_stack[-1] != '(':  # корректное закрытие
                return -1  # не сбалансированное, но это не влияет на max_depth
    return max(depth, 0)  # depth может быть отрицательным, но мы хотим максимум

def find_unmatched(s: str) -> list[int]:
    unmatched = []
    open_stack = []
    for i, ch in enumerate(s):
        if ch == '(':
            open_stack.append(i)
        elif ch == ')':
            if open_stack and open_stack[-1] == i:
                open_stack.pop()
            else:
                unmatched.append(i)  # закрывающий не корректный
    unmatched = sorted(unmatched)
    return unmatched
```
